import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { URL } from 'node:url';
import { runInNewContext } from 'node:vm';
import { buildCandidateWf02, mapCandidateStageEnvelope, validateCandidateWf02 } from '../../tools/build-candidate-wf02.mjs';

// Run with native node --test: tsx instrumentation changes Function.toString().
// This suite evaluates the actual n8n expression generated by the native builder.
const priorPath = '../../n8n/history/3e317cce613e8d2e791fd75ed3ee59cabb470dec7686353b7a99aa5a96a9a41c-wf02-source.json';
const pairs = [
  ['candidate_scan', 'prepare_candidate', 'native.prepare_candidate'],
  ['candidate_scan', 'transcribe_candidate', 'openai.transcribe_candidate'],
  ['candidate_scan', 'extract_candidate', 'openai.extract_candidate'],
  ['candidate_scan', 'select_frames', 'openai.select_frames'],
  ['candidate_scan', 'apply_candidate', 'domain.apply_candidate'],
  ['frame_extract', 'extract_frames', 'native.extract_frames'],
  ['frame_extract', 'apply_frames', 'domain.apply_frames'],
];
const base = { event_id: 'synthetic-vision-event', event_type: 'job.stage_ready', contract_version: '1.0',
  job_id: 'synthetic-vision-job', input_hash: 'a'.repeat(64), correlation_id: 'synthetic-vision-correlation' };
const selectScope = { ...base, kind: 'candidate_scan', stage: 'select_frames' };
const credential = { id: 'synthetic-reference', name: 'Everyone Presentation Studio WF02 local dispatch' };

function evaluateMapper(body, executionId = 'synthetic-execution') {
  const expression = buildCandidateWf02(credential).nodes[1].parameters.jsonOutput;
  assert.ok(expression.startsWith('={{ ') && expression.endsWith(' }}'));
  const result = runInNewContext(expression.slice(3, -2), {
    $: name => { assert.equal(name, 'Receive candidate stage'); return { first: () => ({ json: { body } }) }; },
    $execution: { id: executionId },
  }, { timeout: 100 });
  return JSON.parse(JSON.stringify(result));
}

test('serialized WF02 expression returns exact nine-field metadata work orders for all seven stages', () => {
  for (const [kind, stage, handler] of pairs) {
    const scope = { ...base, kind, stage };
    const expected = { schema_version: '1.0', event_id: base.event_id, job_id: base.job_id, kind, stage,
      input_hash: base.input_hash, correlation_id: base.correlation_id, workflow_execution_id: 'synthetic-execution', handler };
    assert.deepEqual(evaluateMapper(scope), { status: 200, body: expected });
    assert.deepEqual(mapCandidateStageEnvelope(scope, 'synthetic-execution'), { status: 200, body: expected });
  }
});

test('serialized WF02 rejects foreign kind/stage pairs and every non-metadata request field', () => {
  const rejected = [null, [], {}, ...pairs.flatMap(([kind, stage]) => [
    { ...base, kind: kind === 'candidate_scan' ? 'frame_extract' : 'candidate_scan', stage },
    ...['source_text', 'provider_key', 'image_url', 'sampled_frames', 'lease_token', 'binary', 'handler'].map(field => ({ ...base, kind, stage, [field]: 'untrusted' })),
  ]), ...[{ stage: 'constructor' }, { stage: '__proto__' }, { stage: { toString: 'invalid', valueOf: 'invalid' } },
    { event_type: 'job.complete' }, { contract_version: '2.0' }, { event_id: '' }, { job_id: 'invalid\njob' },
    { correlation_id: '' }, { input_hash: 'invalid' }, { kind: 'specs_extract' }].map(patch => ({ ...selectScope, ...patch }))];
  for (const body of rejected) {
    assert.deepEqual(evaluateMapper(body), { status: 400, body: { error: { code: 'DISPATCH_ENVELOPE_INVALID', message: 'Use the published candidate stage envelope.' } } });
  }
  assert.deepEqual(evaluateMapper(selectScope, ''), { status: 500, body: { error: { code: 'WF02_EXECUTION_ID_INVALID', message: 'The candidate work order could not be prepared.' } } });
});

test('saved WF02 export changes only the selection handler and preserves byte-exact prior graph history', () => {
  const bytes = readFileSync(new URL(priorPath, import.meta.url));
  assert.equal(createHash('sha256').update(bytes).digest('hex'), '3e317cce613e8d2e791fd75ed3ee59cabb470dec7686353b7a99aa5a96a9a41c');
  const prior = JSON.parse(bytes.toString('utf8'));
  const saved = JSON.parse(readFileSync(new URL('../../n8n/eps-wf02-candidate-stage.json', import.meta.url), 'utf8'));
  const currentCredential = prior.nodes[0].credentials.httpHeaderAuth;
  assert.equal(validateCandidateWf02(saved, currentCredential), true);
  const expectedGraph = JSON.parse(JSON.stringify(prior).replaceAll('native.select_frames', 'openai.select_frames'));
  assert.deepEqual(saved, expectedGraph);
  assert.deepEqual(buildCandidateWf02(currentCredential), expectedGraph);
});

test('WF02 strict graph validation rejects the old selector, auth bypasses, payload retention and dropped error exits', () => {
  const graph = buildCandidateWf02(credential);
  for (const mutate of [
    value => { value.nodes[1].parameters.jsonOutput = value.nodes[1].parameters.jsonOutput.replace('openai.select_frames', 'native.select_frames'); },
    value => { value.nodes[0].parameters.authentication = 'none'; },
    value => { value.nodes[1].parameters.includeOtherFields = true; },
    value => { value.nodes[1].parameters.options.stripBinary = false; },
    value => { value.settings.saveDataSuccessExecution = 'all'; },
    value => { value.connections['Validate stage envelope'].main[1] = []; },
    value => { value.connections['Respond with work order'].main[1] = []; },
    value => { value.nodes[3].parameters.options.responseCode = 200; },
  ]) {
    const changed = globalThis.structuredClone(graph); mutate(changed);
    assert.throws(() => validateCandidateWf02(changed, credential), { message: 'WF02_GRAPH_UNCONFIRMED' });
  }
});
